/// <summary>
/// Extension class of <c>SalesTable</c> table
/// </summary>
[ExtensionOf(tableStr(SalesTable))]
public final class METSalesTable_Extension
{
}

Method.Source:
/// <summary>
/// Returns the record for <c>METSalesTable</c> table 
/// </summary>
/// <returns><c>METSalesTable</c> Table record</returns>
public METSalesTable metSalesTable()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METSalesTable));
}

    /// <summary>
    /// Pack the SalesTable extension table
    /// </summary>
    /// <param name = "_metSalesTable">METSalesTable to pack</param>
    public void metPackMETSalesTable(METSalesTable _metSalesTable)
    {
        _metSalesTable.SalesTable = this.RecId;

        this.SysExtensionSerializerMap::packExtensionTable(_metSalesTable);

    }

    /// <summary>
    /// Inserts a table buffer into the database.
    /// </summary>
    /// <param name = "_skipMarkup">Skip markup</param>
    public void insert(boolean _skipMarkup)
    {
        boolean intercompanyTransferFulfillment = false; //C - Added for the Task 122004: CB274 - Intercompany Transfers
        METWMSOrderType metWMSOrderType;

        //NS-Added for the Task 122004: CB274 - Intercompany Transfers
        if (this.InterCompanyOrigin == InterCompanyOrigin::Derived)
        {
            METRoute                    routeId;
            SalesTable                  origSalesTable;
            METRouteStopNum             routeStop;
            SalesShippingDateConfirmed  shippingDate;

            changecompany(InventParameters::find().METInterCompanyPurchaseLegalEntity)
            {
                select firstonly METRoute, METRouteStopNum, ShippingDateConfirmed, RecId from origSalesTable
                    where origSalesTable.SalesId == this.InterCompanyOriginalSalesId
                    && origSalesTable.METIntercompanyTransferFulfillment == NoYes::Yes;

                if (origSalesTable.RecId)
                {
                    routeId         = origSalesTable.METRoute;
                    routestop       = origSalesTable.METRouteStopNum;
                    shippingDate    = origSalesTable.ShippingDateConfirmed;
                    metWMSOrderType = origSalesTable.metSalesTable().WMSOrderType;

                    intercompanyTransferFulfillment = true;
                }
            }

            if (intercompanyTransferFulfillment == true)
            {
                this.METRoute               = routeId;
                this.METRouteStopNum        = routestop;
                this.ShippingDateConfirmed  = shippingDate;
            }
        }
        //NE-Added for the Task 122004: CB274 - Intercompany Transfers

        METSalesTable metSalesTable;

        metSalesTable = this.metSalesTable();
        metSalesTable.initValue();
        
        //NS - Added for the Task 122004: CB274 - Intercompany Transfers
        if (intercompanyTransferFulfillment == true)
        {
            metSalesTable.ExcludeFromDualWrite = NoYes::Yes;
            metSalesTable.WMSOrderType = metWMSOrderType;
        }
        //NE - Added for the Task 122004: CB274 - Intercompany Transfers
        
        metSalesTable.IndustryKey = METCustTable::find(this.CustAccount).IndustryKey;
        this.metPackMETSalesTable(metSalesTable);
        
        next insert(_skipMarkup);
    }

    /// <summary>
    /// Updates a table buffer into the database.
    /// </summary>
    public void update()
    {
        SalesTable  salesTableOrig = this.orig();

        if (salesTableOrig.METIOMSyncComplete == NoYes::No && this.METIOMSyncComplete == NoYes::Yes)
        {
            this.METUpdateEventOrderFields();
        }

        if (salesTableOrig.CredManInCreditControl == NoYes::Yes &&
            this.CredManInCreditControl == NoYes::No &&
            this.METCreditCheckSalesOrder == NoYes::Yes)
        {
            this.METCreditCheckSalesOrder = NoYes::No;
        }

        next update();

        //CB616_TMSEngineSOCancellation
        //TMS Engin SO Cancellation processing
        if (salesTableOrig.SalesStatus != SalesStatus::Canceled && this.SalesStatus == SalesStatus::Canceled)
        {
            METTMSProcessingStatus::insertTMSProcessingStatus(METTMSOrderType::SalesOrder, this.SalesId, METTMSEngineExecutionMode::SalesOrderCancellation);

            this.metUpdateWaveStatus();
        }

        //CBNF019_Observability_SalesOrderExtracted
        if (salesTableOrig.METOrderExtractStatus != METOrderExtractStatus::Extracted
            && this.METOrderExtractStatus == METOrderExtractStatus::Extracted && this.SalesId != '')
        {
            METTelemetrySOExtractionInfoEvent SOExtractedInfoEvent = METTelemetrySOExtractionInfoEvent::construct();
           
            SOExtractedInfoEvent.addRunTimePropertyToAppinsights(this);

            SOExtractedInfoEvent.processEvent(METTelemetryEventNames::SOPickedEvent);
        }
    }

    /// <summary>
    /// Updates wave status, If all sales orders in the wave are cancelled, then update wave status to closed, otherwise keep the wave status unchanged.
    /// </summary>
    public void metUpdateWaveStatus()
    {
        METWaveLine     metWaveLine, metWaveLineCheck;
        METWaveTable    metWaveTable;
        SalesTable      salesTableCheck;

        // Get WaveId for this sales order
        select firstonly WaveId from metWaveLine
            where metWaveLine.DocumentNumber == this.SalesId
            && metWaveLine.Type          == METType::SalesOrder;

        if (metWaveLine.WaveId)
        {
            // Check if any active order still exists in this wave
            select firstonly RecId from salesTableCheck
                exists join metWaveLineCheck
                where metWaveLineCheck.WaveId         == metWaveLine.WaveId
                    && metWaveLineCheck.DocumentNumber == salesTableCheck.SalesId
                    && salesTableCheck.SalesStatus != SalesStatus::Canceled;

            if (!salesTableCheck.RecId)
            {
                ttsbegin;
                select forupdate metWaveTable
                    where metWaveTable.WaveId == metWaveLine.WaveId;

                if (metWaveTable && metWaveTable.WaveStatus != METCSDWaveStatus::Closed)
                {
                    metWaveTable.WaveStatus = METCSDWaveStatus::Closed;
                    metWaveTable.update();
                }
                ttscommit;
            }
        }
    }

    /// <summary>
    /// Updates extract status.
    /// </summary>
    void  metUpdateExtractStatus()
    {
        SalesTableType  salesTableType;

        salesTableType = this.type();
        salesTableType.metUpdateExtractStatus();
    }

