    /// <summary>
    /// Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
    /// Method to determine if at least one <c>SalesLine</c> has reservedPhysical > 0
    /// </summary>
    /// <returns>true if at least one <c>SalesLine</c> has reservedPhysical > 0; otherwise, false.</returns>
    public boolean METExistSalesLineReservedPhysical()
    {
        SalesLine   salesLine;
        
        while select salesLine
               where salesLine.SalesId == this.SalesId
        {
            if (salesLine.reservedPhysical())
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// validate sales table field
    /// </summary>
    /// <param name = "_fieldIdToCheck">Field id to check</param>
    /// <returns>True if field is valudated; otherwise, false</returns>
    public boolean validateField(FieldId _fieldIdToCheck)
    {
        boolean ret;
    
        ret = next validateField(_fieldIdToCheck);
    
        switch (_fieldIdToCheck)
        {
            Case fieldNum(SalesTable, METRoute):

                METValidateRouteHelper validateRouteHelper = new METValidateRouteHelper();
                
                if (!validateRouteHelper.validateRouteForUpperCase(this.METRoute) || !validateRouteHelper.validateRouteLength(strLen(this.METRoute)) ||
                    !validateRouteHelper.validateForAlphaNumeric(this.METRoute))
                {
                    ret = false;
                }
                break;

            case fieldNum(SalesTable, METRouteStopNum):
          
                METValidateRouteHelper validateRouteHelperLoc = new METValidateRouteHelper();
                ret = validateRouteHelperLoc.validateRouteStop(this.METRouteStopNum, strLen(int2Str(this.METRouteStopNum)));
                break;
        }

        return ret;
    }

    /// <summary>
    /// Check for return credit invoice
    /// </summary>
    /// <returns>true if the sales order is return credit invoice</returns>
    public boolean checkForReturnCreditInvoice()
    {
        boolean isReturnCreditInvoice = false;

        METSalesType metOrderType = METVendParameters::find().OrderType;

        if (this.SalesType == SalesType::ReturnItem && enum2Str(this.SalesType) == enum2Str(metOrderType))
        {
            isReturnCreditInvoice = true;            
        }       

        return isReturnCreditInvoice;
    }

    /// <summary>
    /// Check for chargethrough claims
    /// </summary>
    /// <returns>true if the sales order chargethrough claims</returns>
    public boolean checkForChargeThroughClaims()
    {
        boolean isChargeThroughClaims = false;

        if (this.SalesType == SalesType::Sales 
            && this.METSalesOrderType == enum2Str(METInvoiceType::ChargeThrough)
            && (this.METInvoiceType == METInvoiceTypeSO::ChargeThroughClaim 
                ||  this.METInvoiceType == METInvoiceTypeSO::CrossDockClaim))
        {
            str chargeThroughInvoiceType = METVendParameters::find().ChargeThroughInvoiceType;

            container chargeThroughInvoice = str2con(chargeThroughInvoiceType, METConstants::Semicolon);

            if (conLen(chargeThroughInvoice) > 0)
            {  
                if (conFind(chargeThroughInvoice, enum2Str(this.METInvoiceType)))
                {
                    isChargeThroughClaims = true;
                }
            }           

        }

        return isChargeThroughClaims;
        
    }

    public boolean validateWrite()
    {
        boolean ret = next validateWrite();

        if (ret && METSecurityPolicyHelper::isRoleActiveForCurrentUser(roleStr(METInventLocationPolicyRole)))
        {
            if (this.inventLocationId)
            {
                METUserSecurityGroupList        securityGroupList;
                METUserSecurityWarehouseList    warehouseList;
                
                select firstonly RecId from warehouseList
                    where warehouseList.InventLocationId == this.inventLocationId
                       && warehouseList.Company == this.dataAreaId
                       && warehouseList.RestrictAllReturnOrders == NoYes::Yes
                    exists join securityGroupList
                        where securityGroupList.UserSecurityGroupId == warehouseList.UserSecurityGroupId
                           && securityGroupList.UserId == curUserId();
                           
                if (warehouseList.RecId)
                {
                    ret = checkFailed(strFmt("@MET:WarehouseRORestricted", this.inventLocationId));
                }
            }
        }

        return ret;
    }

    boolean canCustomerBeUpdated(DocumentStatus _documentStatus)
    {
        boolean  ok = next canCustomerBeUpdated(_documentStatus);

        if (!ok && _documentStatus == DocumentStatus::Invoice && this.RecId)
        {
            METVendParameters vendParameters;

            select firstonly SalesOrderType from vendParameters;
       
            CustVendorBlocked   blockStatus   = CustTable::find(this.CustAccount).Blocked;

            // Verify if the CustAccount is blocked post sales invoice should not trigger
            if (this.METSalesOrderType == vendParameters.SalesOrderType && blockStatus == CustVendorBlocked::METSalesinvoice)
            {
                ok = true;
            }
        }

        return ok;
    }

    /// <summary>
    /// Creates markups for the sales order.
    /// </summary>
    /// <param name="_deleteExistingMarkupTrans">
    /// Determines whether to delete existing markups before creating the new.
    /// </param>
    /// <param name="_createTieredMarkups">
    /// Determines whether to create tiered markups. If this parameter is true then _deleteExistingMarkupTrans will be reset to false.
    /// In this case only existing tiered markups will be deleted before creating the new.
    /// </param>
    public void createMarkupTrans(boolean _deleteExistingMarkupTrans,
                                         boolean _createTieredMarkups)
    {
        if (this is SalesTable)
        {
            this.skipBusinessEvents(true);
        }

        next createMarkupTrans(_deleteExistingMarkupTrans, _createTieredMarkups);
    }

    /// <summary>
    /// Bug 416940: Manage Legislative Charges - Error in in CPI Sales order Repricing batch job
    /// </summary>
    public void metDeletePriceComponents()
    {
        METSalesLinePriceComponent          salesLinePriceComponent;
        METSalesLinePriceComponentDetail    salesLinePriceComponentDetail;
        SalesLine salesLine;
        
        ttsbegin;
        // delete price compoments and detail records
        delete_from salesLinePriceComponent
            exists join salesLine
              where salesLine.SalesId == this.SalesId
                 && salesLinePriceComponent.InventTransId == salesLine.InventTransId;

        delete_from salesLinePriceComponentDetail
              exists join salesLine
              where salesLine.SalesId == this.SalesId
                 && salesLinePriceComponentDetail.InventTransId == salesLine.InventTransId;
        ttscommit;
    }
